const slice21 = createSlice({
  creators: (ctx) => ({ asyncThunk: asyncThunkCreator(ctx) }),
  name: 'slice21',
  initialState: { list: [] as Item21[], status: 'idle' },
  reducers: (create) => ({
    added: create.reducer<Item21>((state, action) => {
      state.list.push(action.payload)
    }),
    cleared: create.reducer((state) => {
      state.list = []
    }),
    fetchItem: create.asyncThunk(
      async (id: string) => ({ id, label21: id }) as Item21,
      {
        pending(state) {
          state.status = 'pending'
        },
        fulfilled(state, action) {
          state.status = 'done'
          state.list.push(action.payload)
        },
      },
    ),
  }),
  selectors: {
    selectList: (state) => state.list,
  },
})
export const reducer21 = slice21.reducer
export const actions21 = slice21.actions
export const selectors21 = slice21.selectors

